303			wg.Add(1)
304			go func(i int) {
305				defer wg.Done()
306				got, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, expiryOK.Add(time.Duration(i)*time.Hour))
307				mu.Lock()
308				defer mu.Unlock()
309				if err != nil || got != first {
310					badRetries++
311				}
312			}(i)
313		}
314		for i := 0; i < 2; i++ {
315			wg.Add(1)
316			go func(i int) {
317				defer wg.Done()
318				_, err := s.Use(fmt.Sprintf("u%d", i), "c1", 1, nowOK)
