// TestReserveConfirmsExpiryDuringStockAccounting 验证新预留的库存核算会确认
// 到期承诺；即使本次预留因库存不足失败，已确认的到期也不回退。
func TestReserveConfirmsExpiryDuringStockAccounting(t *testing.T) {
	s := expiryStore(t, 5)
